begin;
do $$
declare a uuid;d uuid;d2 uuid; result jsonb; original_trial timestamptz; deadline timestamptz; count_before bigint;
begin
 select user_id into a from public.portal_staff where role='admin' and active and not must_change_password limit 1;
 if a is null then raise exception 'Missing test admin';end if;
 select count(*) into count_before from public.portal_managed_devices;
 result:=public.portal_roku_operation('register',repeat('1',64),'ROKU-TEST0001-DEVICE01',repeat('a',64),null,'{"name":"Synthetic Roku"}');
 if result->'license'->>'status'<>'awaiting_activation' then raise exception 'Initial status';end if;
 select id into d from public.portal_roku_devices where client_hash=repeat('1',64);
 result:=public.portal_roku_operation('status',repeat('1',64),'ROKU-TEST0001-DEVICE01');if result->'license'->>'status'<>'awaiting_activation' then raise exception 'Status before binding';end if;
 perform public.portal_roku_operation('register',repeat('1',64),'ROKU-TEST0001-DEVICE01',repeat('a',64),null,'{"name":"Synthetic Roku"}');
 if (select count(*) from public.portal_roku_devices where client_hash=repeat('1',64))<>1 then raise exception 'Duplicate';end if;
 begin perform public.portal_roku_operation('register',repeat('1',64),'ROKU-TEST0002-DEVICE02',repeat('a',64),null,'{"name":"Reuse"}');raise exception 'Expected conflict';exception when others then if sqlerrm<>'ROKU_CONFLICT' then raise;end if;end;
 begin perform public.portal_roku_operation('register',repeat('2',64),'ROKU-TEST0001-DEVICE01',repeat('a',64),null,'{"name":"Collision"}');raise exception 'Expected conflict';exception when others then if sqlerrm<>'ROKU_CONFLICT' then raise;end if;end;
 begin perform public.portal_roku_operation('register',repeat('1',64),'ROKU-TEST0001-DEVICE01',repeat('b',64),null,'{"name":"Hijack"}');raise exception 'Expected key rejection';exception when others then if sqlerrm<>'ROKU_IDENTITY' then raise;end if;end;
 begin perform public.portal_roku_operation('bind',null,'ROKU-TEST0001-DEVICE01',repeat('b',64));raise exception 'Expected key rejection';exception when others then if sqlerrm<>'ROKU_IDENTITY' then raise;end if;end;
 result:=public.portal_roku_operation('bind',null,'ROKU-TEST0001-DEVICE01',repeat('a',64));
 if result->'license'->>'status'<>'active' or result->'license'->>'access_source'<>'trial' then raise exception 'Trial access';end if;
 result:=public.portal_roku_operation('status',repeat('1',64),'ROKU-TEST0001-DEVICE01');if result->'license'->>'can_play'<>'true' then raise exception 'Status after binding';end if;
 select trial_started_at into original_trial from public.portal_roku_devices where id=d;
 perform public.portal_roku_operation('playlist',null,'ROKU-TEST0001-DEVICE01',repeat('a',64),null,'{"name":"Synthetic list","kind":"m3u","credentials":{"url":"http://roku-test.invalid/list"},"origin":"http://roku-test.invalid"}');
 if (select trial_started_at from public.portal_roku_devices where id=d)<>original_trial then raise exception 'Trial restarted';end if;
 result:=public.portal_roku_operation('sync',repeat('1',64),'ROKU-TEST0001-DEVICE01',repeat('a',64));
 if result->'playlist'->>'kind'<>'m3u' then raise exception 'Sync missing';end if;
 update public.portal_roku_devices set trial_expires_at=now()-interval '1 day' where id=d;
 result:=public.portal_roku_operation('sync',repeat('1',64),'ROKU-TEST0001-DEVICE01',repeat('a',64));
 if result->'license'->>'status'<>'expired' or result->'playlist'<>'null'::jsonb then raise exception 'Expired credentials leaked';end if;
 perform public.portal_roku_operation('admin',null,null,null,a,jsonb_build_object('id',d,'operation','renew','payment_reference','roku-synthetic-receipt-001','amount_cents',2490));
 select paid_until into deadline from public.portal_roku_devices where id=d;
 if deadline<now()+interval '364 days' then raise exception 'Annual renewal';end if;
 perform public.portal_roku_operation('admin',null,null,null,a,jsonb_build_object('id',d,'operation','renew','payment_reference','roku-synthetic-receipt-001','amount_cents',2490));
 if (select paid_until from public.portal_roku_devices where id=d)<>deadline then raise exception 'Duplicate receipt extended twice';end if;
 perform public.portal_roku_operation('admin',null,null,null,a,jsonb_build_object('id',d,'operation','renew','payment_reference','roku-synthetic-receipt-002','amount_cents',2490));
 if (select paid_until from public.portal_roku_devices where id=d)<>deadline+interval '1 year' then raise exception 'Remaining validity lost';end if;
 perform public.portal_roku_operation('admin',null,null,null,a,jsonb_build_object('id',d,'operation','update','active',false));
 result:=public.portal_roku_operation('sync',repeat('1',64),'ROKU-TEST0001-DEVICE01',repeat('a',64));
 if result->'license'->>'status'<>'blocked' or result->'playlist'<>'null'::jsonb then raise exception 'Blocked credentials leaked';end if;
 perform public.portal_roku_operation('admin',null,null,repeat('b',64),a,jsonb_build_object('id',d,'operation','rebind','reason','Synthetic rebind','restore',true));
 begin perform public.portal_roku_operation('sync',repeat('1',64),'ROKU-TEST0001-DEVICE01',repeat('a',64));raise exception 'Expected old key rejected';exception when others then if sqlerrm<>'ROKU_IDENTITY' then raise;end if;end;
 perform public.portal_roku_operation('admin',null,null,null,a,jsonb_build_object('id',d,'operation','lifetime','lifetime',true,'reason','Synthetic lifetime'));
 result:=public.portal_roku_license(d);if result->>'can_play'<>'true' or result->>'lifetime'<>'true' then raise exception 'Lifetime access';end if;
 insert into public.portal_server_codes(code,host,active,validity,expires_at,revoked,updated_by) values('roku_qa_only','http://roku-code-qa.invalid',true,'annual',now()+interval '1 year',false,a);
 perform public.portal_roku_operation('playlist',null,'ROKU-TEST0001-DEVICE01',repeat('b',64),null,'{"name":"Host test","kind":"xtream","credentials":{"host":"http://roku-code-qa.invalid","username":"test","password":"test"},"origin":"http://roku-code-qa.invalid"}');
 result:=public.portal_roku_license(d);if result->>'access_source'<>'server_code' or result->>'can_play'<>'true' then raise exception 'Code validity';end if;
 update public.portal_server_codes set revoked=true,restricted_at=now()+interval '1 second' where code='roku_qa_only';
 result:=public.portal_roku_operation('sync',repeat('1',64),'ROKU-TEST0001-DEVICE01',repeat('b',64));if result->'license'->>'can_play'<>'false' or result->'playlist'<>'null'::jsonb then raise exception 'Revoked code leaked credentials';end if;
 begin perform public.portal_roku_operation('admin',null,null,null,null,jsonb_build_object('id',d,'operation','lifetime','lifetime',true,'reason','Forbidden actor'));raise exception 'Expected forbidden actor';exception when others then if sqlerrm not in ('ROKU_FORBIDDEN','ROKU_IDENTITY') then raise;end if;end;
 if has_table_privilege('anon','public.portal_roku_devices','select') or has_table_privilege('authenticated','public.portal_roku_playlists','select') or has_function_privilege('anon','public.portal_roku_operation(text,text,text,text,uuid,jsonb)','execute') then raise exception 'Unsafe grants';end if;
 if (select count(*) from public.portal_managed_devices)<>count_before then raise exception 'Legacy records changed';end if;
end $$;
rollback;
